import { unlink } from 'node:fs/promises';
import path from 'node:path';
import type Database from 'better-sqlite3';
import { HttpError } from './validation.js';

// Legacy GLB IDs need not be UUIDs. Allow only single file names generated by the library.
const storedFilename = /^[a-zA-Z0-9_-]{1,100}\.(?:glb|json|png|jpg)(?![\s\S])/;
const reservedName = /^(?:con|prn|aux|nul|com[0-9]|lpt[0-9])\./i;
const isStoredFilename = (filename: string) => storedFilename.test(filename) && !reservedName.test(filename);

export interface ResourceFileDeletions {
  enqueue(filename: string): void;
  enqueueThumbnail(versionId: string, filename: string | null): void;
  flush(): Promise<void>;
  close(): void;
}

export function requireReceiptRecord(db: Database.Database, id: string) {
  if (!db.prepare('SELECT 1 FROM records WHERE id=?').get(id)) {
    throw new HttpError(410, '此请求对应的记录已被删除，不能重新使用该请求编号', 'RECORD_DELETED');
  }
}

export function openResourceFileDeletions(db: Database.Database, directory: string, syncDirectory: (directory: string) => Promise<void>): ResourceFileDeletions {
  db.exec('CREATE TABLE IF NOT EXISTS pending_file_deletions (filename TEXT PRIMARY KEY)');
  const insert = db.prepare('INSERT OR IGNORE INTO pending_file_deletions(filename) VALUES (?)');
  const pending = db.prepare('SELECT filename FROM pending_file_deletions').pluck();
  const remove = db.prepare('DELETE FROM pending_file_deletions WHERE filename=?');
  let running: Promise<void> | undefined;
  let stopped = false;

  async function drain() {
    const filenames = pending.all() as string[];
    if (!filenames.length) return;
    // Team screenshot tables are created during startup, before the first drain.
    // Also protect a thumbnail kept as a dashboard screenshot's unbind fallback.
    const referencedThumbnail = db.prepare(`SELECT 1 FROM versions WHERE has_thumbnail=1 AND
      COALESCE(thumbnail_path,id || '.png')=? COLLATE NOCASE
      UNION ALL SELECT 1 FROM team_dashboard_screenshots WHERE filename=? COLLATE NOCASE OR
      (previous_thumbnail=1 AND COALESCE(previous_path,version_id || '.png')=? COLLATE NOCASE) LIMIT 1`);
    const referencedSource = db.prepare('SELECT 1 FROM versions WHERE id=? COLLATE NOCASE AND source_kind=? LIMIT 1');
    const removed: string[] = [];
    for (const filename of filenames) {
      if (stopped) return;
      if (!isStoredFilename(filename)) {
        remove.run(filename);
        continue;
      }
      const extension = filename.slice(-4);
      const referenced = extension === '.png' || extension === '.jpg'
        ? referencedThumbnail.get(filename, filename, filename)
        : referencedSource.get(filename.slice(0, filename.lastIndexOf('.')), extension === '.glb' ? 'glb' : 'chat3d');
      if (referenced) {
        remove.run(filename);
        continue;
      }
      try { await unlink(path.join(directory, filename)); }
      catch (error) {
        if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
          console.error('清理已删除文件失败，将重试', filename, error);
          continue;
        }
      }
      removed.push(filename);
    }
    if (!removed.length || stopped) return;
    // On platforms with directory fsync, persist the unlinks before acknowledging them in SQLite.
    await syncDirectory(directory);
    if (!stopped) db.transaction(() => { for (const filename of removed) remove.run(filename); })();
  }

  function flush(): Promise<void> {
    if (stopped) return Promise.resolve();
    // A mutation may have queued more work after an active drain took its snapshot.
    const next = (running ?? Promise.resolve()).then(() => { if (!stopped) return drain(); })
      .catch(error => console.error('清理队列处理失败，将重试', error))
      .finally(() => { if (running === next) running = undefined; });
    return running = next;
  }

  const retry = setInterval(() => { if (!running) void flush(); }, 5000);
  retry.unref();
  return {
    enqueue(filename: string) { if (isStoredFilename(filename)) insert.run(filename); },
    enqueueThumbnail(versionId: string, filename: string | null) {
      const target = filename ?? `${versionId}.png`;
      if ((target.endsWith('.png') || target.endsWith('.jpg')) && isStoredFilename(target)) insert.run(target);
    },
    flush,
    close() { stopped = true; clearInterval(retry); },
  };
}
